/*
 * Zephyr ADC example for nrf52840dk/nrf52840
 * Reads channel 0 with hardware oversampling (2^4 = 16 samples)
 * and prints the averaged 12‑bit raw value every second.
 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/util.h>
#include <zephyr/devicetree.h>

#define ADC_NODE DT_ALIAS(adc0)

/* Static buffer for ADC sample(s) */
static int16_t adc_sample[1];

/* ADC sequence configuration */
static const struct adc_sequence adc_seq = {
	.channels = BIT(0),                 /* channel 0 */
	.buffer   = (uint8_t *)adc_sample,
	.buffer_size = sizeof(adc_sample),
	.resolution = 12,
	.oversampling = 4,                  /* hardware averaging over 16 samples */
};

/* ADC channel configuration */
static const struct adc_channel_cfg adc_chan_cfg = {
	.gain           = ADC_GAIN_1,
	.reference      = ADC_REF_INTERNAL,
	.acquisition_time = ADC_ACQ_TIME_DEFAULT,
	.channel_id     = 0,
};

void main(void)
{
	const struct device *adc_dev;
	int ret;

	/* Get ADC device from device tree */
	adc_dev = DEVICE_DT_GET(ADC_NODE);
	if (!device_is_ready(adc_dev)) {
		printk("ADC device not ready\n");
		return;
	}

	/* Configure ADC channel */
	ret = adc_channel_setup(adc_dev, &adc_chan_cfg);
	if (ret) {
		printk("adc_channel_setup failed: %d\n", ret);
		return;
	}

	printk("ADC initialized. Reading channel 0 with 12-bit resolution and "
	       "oversampling 2^4...\n");

	while (1) {
		ret = adc_read(adc_dev, &adc_seq);
		if (ret == 0) {
			printk("ADC raw: %d\n", adc_sample[0]);
		} else {
			printk("adc_read failed: %d\n", ret);
		}
		k_msleep(1000);
	}
}
